# OSMIUM AUDIT LOGGER
$script:OsmiumAuditPath=Join-Path $env:LOCALAPPDATA "OsmiumTerminal\logs\audit.jsonl"
function Get-OsmiumAuditHash { param($Record) $core=[ordered]@{TimestampUtc=$Record.TimestampUtc;EventId=$Record.EventId;EventType=$Record.EventType;Tool=$Record.Tool;Target=$Record.Target;Risk=$Record.Risk;Fingerprint=$Record.Fingerprint;Decision=$Record.Decision;Outcome=$Record.Outcome;TransactionId=$Record.TransactionId;Details=$Record.Details;PreviousHash=$Record.PreviousHash}; $json=ConvertTo-Json -InputObject $core -Depth 8 -Compress; $sha=[Security.Cryptography.SHA256]::Create(); try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($json)))).Replace("-","")}finally{$sha.Dispose()} }
function Test-OsmiumAuditLines { param([string[]]$Lines) $previous="GENESIS"; foreach($line in $Lines){if([string]::IsNullOrWhiteSpace($line)){throw "Audit integrity failure: blank record."}; $r=ConvertFrom-Json -InputObject $line -ErrorAction Stop; if($r.PreviousHash -ne $previous){throw "Audit integrity failure: broken hash chain."}; $expected=Get-OsmiumAuditHash $r; if($r.Hash -ne $expected){throw "Audit integrity failure: record hash mismatch."}; $previous=$r.Hash}; return $previous }
function Write-OsmiumAuditEvent { param([string]$EventType,[string]$Tool="",[string]$Target="",[string]$Risk="",[string]$Fingerprint="",[string]$Decision="",[string]$Outcome="",[string]$TransactionId="",[string]$Details="") $dir=Split-Path $script:OsmiumAuditPath -Parent; if(-not(Test-Path -LiteralPath $dir)){New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop|Out-Null}; $fs=$null; try{$fs=[IO.File]::Open($script:OsmiumAuditPath,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None); $fs.Position=0; $reader=New-Object IO.StreamReader($fs,[Text.Encoding]::UTF8,$true,1024,$true); $content=$reader.ReadToEnd(); $reader.Dispose(); $lines=@(); if(-not[string]::IsNullOrEmpty($content)){$lines=@($content -split "`r?`n" | Where-Object {$_ -ne ""})}; $previous="GENESIS"; if($lines.Count -gt 0){$previous=Test-OsmiumAuditLines -Lines $lines}; $r=[pscustomobject][ordered]@{TimestampUtc=[DateTime]::UtcNow.ToString("o");EventId=[guid]::NewGuid().ToString("N");EventType=$EventType;Tool=$Tool;Target=$Target;Risk=$Risk;Fingerprint=$Fingerprint;Decision=$Decision;Outcome=$Outcome;TransactionId=$TransactionId;Details=$Details;PreviousHash=$previous;Hash=""}; $r.Hash=Get-OsmiumAuditHash $r; $json=ConvertTo-Json -InputObject $r -Depth 8 -Compress; $bytes=[Text.Encoding]::UTF8.GetBytes($json+[Environment]::NewLine); $fs.Position=$fs.Length; $fs.Write($bytes,0,$bytes.Length); $fs.Flush($true); return $r.Hash}finally{if($null -ne $fs){$fs.Dispose()}} }
